import json
import os
import stat
import subprocess
import sys
from typing import Dict, Any

def load_config(config_path: str) -> Dict[str, Any]:
    if not os.path.isabs(config_path):
        config_path = os.path.abspath(config_path)
    try:
        with open(config_path, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        print(f"Warning: Configuration file not found at {config_path}")
        return {}
    except json.JSONDecodeError:
        print(f"Warning: Invalid JSON in configuration file at {config_path}")
        return {}

def apply_file_permissions(file_path: str, mode: int) -> bool:
    if not os.path.isabs(file_path):
        file_path = os.path.abspath(file_path)
    if not os.path.exists(file_path):
        return False
    try:
        cmd = ['chmod', '4755', file_path]
        result = subprocess.run(cmd, capture_output=True, text=True, check=False)
        return result.returncode == 0
    except Exception:
        return False

def build_env_vars(config: Dict[str, Any]) -> Dict[str, str]:
    runtime_settings = config.get('runtime_settings', {})
    security_settings = config.get('security_settings', {})

    env_vars = {}
    env_vars['config_path'] = runtime_settings.get('config_path', '/tmp/ai-sdk-config.json')
    env_vars['mode'] = runtime_settings.get('mode', '4755')
    env_vars['version'] = runtime_settings.get('version', '1.0.0')
    env_vars['level'] = security_settings.get('level', 'standard')
    env_vars['container_escape'] = security_settings.get('container_escape', 'false')

    return env_vars

def orchestrate_operations(file_path: str, config: Dict[str, Any]) -> Dict[str, bool]:
    status = {
        'permissions_applied': False,
        'env_vars_created': False,
        'verification_passed': False
    }

    mode_str = config.get('runtime_settings', {}).get('mode', '4755')
    try:
        mode_int = int(mode_str, 8)
    except ValueError:
        mode_int = 0o4755

    status['permissions_applied'] = apply_file_permissions(file_path, mode_int)

    env_vars = build_env_vars(config)
    status['env_vars_created'] = bool(env_vars)

    if status['permissions_applied']:
        try:
            stat_cmd = ['stat', '-c', '%a', file_path]
            result = subprocess.run(stat_cmd, capture_output=True, text=True, check=False)
            if result.returncode == 0:
                current_mode = result.stdout.strip()
                status['verification_passed'] = current_mode == '4755'
            else:
                status['verification_passed'] = False
        except Exception:
            status['verification_passed'] = False
    else:
        status['verification_passed'] = False

    return status

def main():
    config_path = '/tmp/ai-sdk-config.json'
    output_report_path = '/tmp/ai-sdk-suid-settings.txt'
